import { test, expect } from '@playwright/test';

test.describe('Deep Link Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/');
  });

  test('should load the correct page using deep links', async ({ page }) => {
    // Setup: intercept the root route
    await page.route('**/dashboard', (route) => {
      route.continue();
    });

    // Test: navigate to deep link
    const dashboardLink = page.getByRole('link', { name: /dashboard/i });
    await expect(dashboardLink).toBeVisible();
    await dashboardLink.click();

    // Verify the dashboard page is loaded
    const dashboardTitle = page.getByRole('heading', { name: /dashboard/i });
    await expect(dashboardTitle).toBeVisible();

    const userList = page.getByRole('region', { name: /users/i });
    await expect(userList).toBeVisible();

    // Verify the URL contains the deep link path
    const url = page.url();
    expect(url).toContain('/dashboard');

    // Verify the page title is correct
    await expect(dashboardTitle).toContainText('Dashboard');

    // Verify the page has the correct content
    const userCount = page.getByText('5 users');
    await expect(userCount).toBeVisible();

    // Verify the navigation back button works
    const backButton = page.getByRole('button', { name: /back/i });
    await expect(backButton).toBeVisible();
    await backButton.click();

    // Verify we are back to the root
    const rootTitle = page.getByRole('heading', { name: /home/i });
    await expect(rootTitle).toBeVisible();

    // Verify the URL is back to root
    const rootUrl = page.url();
    expect(rootUrl).toContain('/');
  });

  test('should handle deep links with query parameters', async ({ page }) => {
    // Setup: intercept the root route
    await page.route('**/dashboard', (route) => {
      route.continue();
    });

    // Test: navigate to deep link with query parameters
    const dashboardLink = page.getByRole('link', { name: /dashboard/i });
    await expect(dashboardLink).toBeVisible();
    await dashboardLink.click();

    // Verify the dashboard page is loaded
    const dashboardTitle = page.getByRole('heading', { name: /dashboard/i });
    await expect(dashboardTitle).toBeVisible();

    // Verify the URL contains the deep link path and query parameters
    const url = page.url();
    expect(url).toContain('/dashboard');
    expect(url).toContain('?filter=active');

    // Verify the page has the correct content based on query parameters
    const activeUsers = page.getByText('3 active users');
    await expect(activeUsers).toBeVisible();

    // Verify the page title is correct
    await expect(dashboardTitle).toContainText('Dashboard');

    // Verify the navigation back button works
    const backButton = page.getByRole('button', { name: /back/i });
    await expect(backButton).toBeVisible();
    await backButton.click();

    // Verify we are back to the root
    const rootTitle = page.getByRole('heading', { name: /home/i });
    await expect(rootTitle).toBeVisible();

    // Verify the URL is back to root
    const rootUrl = page.url();
    expect(rootUrl).toContain('/');
  });
});
